"use strict";(self.webpackChunkwiki_es=self.webpackChunkwiki_es||[]).push([["81377"],{17946(e){e.exports=JSON.parse('{"tag":{"label":"Jetson","permalink":"/es/tags/jetson","allTagsPath":"/es/tags","count":7,"items":[{"id":"Edge/NVIDIA_Jetson/Application/Computer_Vision/es_Streaming_Vision_Agent_on_Jetson","title":"Agente de Visi\xf3n en Streaming en Jetson","description":"Implementa un Agente de Visi\xf3n en Streaming en NVIDIA Jetson con memoria multimodal rodante dual Qwen3-VL-2B y una interfaz Ask en vivo","permalink":"/es/streaming_vision_agent_on_jetson"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/es_reComputer_Robotics_Hardware_Interfaces_Usage","title":"Hardware y Uso de Interfaces de reComputer Robotics","description":"Esta wiki proporciona una introducci\xf3n completa a las caracter\xedsticas de hardware y el uso de interfaces de la placa portadora reComputer Jetson Robotics J401. Cubre especificaciones detalladas, m\xf3dulos compatibles, instrucciones de configuraci\xf3n y gu\xedas pr\xe1cticas para usar varias interfaces como M.2, Ethernet, USB, CAN, UART, I2C y expansi\xf3n de c\xe1mara GMSL2, ayudando a los usuarios a comenzar r\xe1pidamente con el desarrollo de rob\xf3tica en la plataforma J401.","permalink":"/es/recomputer_robotics_j401_hardware_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/es_reComputer_Robotics_Getting_Started","title":"Introducci\xf3n a reComputer Robotics","description":"La reComputer Robotics J401 es una placa portadora de IA de borde de alto rendimiento dise\xf1ada para aplicaciones avanzadas de rob\xf3tica. Es compatible con los m\xf3dulos NVIDIA Jetson Orin Nano y Orin NX en modo Super/MAXN, ofreciendo hasta 157 TOPS de potencia de c\xf3mputo de IA. La placa ofrece amplias opciones de conectividad, incluyendo Ethernet Gigabit dual, m\xfaltiples puertos USB 3.2, CAN, ranuras M.2 para m\xf3dulos 5G/Wi\u2011Fi/BT y compatibilidad opcional con c\xe1maras GMSL2. Con JetPack 6 preinstalado, garantiza un despliegue fluido para el desarrollo de rob\xf3tica. El dise\xf1o robusto admite un amplio rango de temperaturas de funcionamiento e incluye un disipador de calor con ventilador preinstalado. La configuraci\xf3n implica flashear el sistema operativo JetPack en un SSD NVMe usando un PC host Ubuntu compatible, seguido de la configuraci\xf3n del hardware y el uso de las interfaces. Se proporcionan especificaciones detalladas de hardware, dibujos mec\xe1nicos y recursos t\xe9cnicos para desarrolladores, junto con canales de soporte t\xe9cnico y de comunidad para resoluci\xf3n de problemas y discusi\xf3n.","permalink":"/es/recomputer_robotics_j401_getting_started"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Super/es_reComputer_Super_vs_Classic_Next-Gen_AI_Performance_in_Edge_Inferencing","title":"reComputer Super vs Classic Rendimiento de IA de Nueva Generaci\xf3n en Inferencia Edge","description":"Este art\xedculo destaca el rendimiento superior de IA del reComputer Super comparado con el reComputer Classic, demostrando hasta un aumento de 1.7x en potencia de c\xf3mputo de IA con el NVIDIA Jetson Orin NX 16GB. A trav\xe9s de benchmarks pr\xe1cticos en generaci\xf3n de texto de IA usando el modelo DeepSeek-R1:7B con Ollama, y procesamiento de video de IA usando el modelo de detecci\xf3n de objetos YOLOv11, los resultados muestran que el reComputer Super ofrece velocidades de inferencia significativamente m\xe1s r\xe1pidas y frecuencias de GPU m\xe1s altas. Notablemente, procesa aproximadamente 2.37 veces m\xe1s im\xe1genes por segundo que el Classic. El art\xedculo tambi\xe9n explica la importancia de evaluar el rendimiento bas\xe1ndose en los FPS reportados por terminal en lugar de los FPS en pantalla, que pueden estar limitados por factores de pantalla y sistema.","permalink":"/es/recomputer_jetson_super_performance"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J401/es_Robotics_J401_carrierboard_Hardware_Interfaces_Usage","title":"Uso de interfaces","description":"Este wiki proporciona una introducci\xf3n completa a las caracter\xedsticas de hardware y al uso de las interfaces de la carrier board reComputer Jetson Robotics J401. Cubre especificaciones detalladas, m\xf3dulos compatibles, instrucciones de configuraci\xf3n y gu\xedas pr\xe1cticas para usar varias interfaces como M.2, Ethernet, USB, CAN, UART, I2C y expansi\xf3n de c\xe1mara GMSL2, ayudando a los usuarios a comenzar r\xe1pidamente con el desarrollo de rob\xf3tica en la plataforma J401.","permalink":"/es/recomputer_jetson_robotics_j401_getting_started"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J601/es_Robotics_J601_carrierboard_Hardware_Interfaces_Usage","title":"Uso de interfaces","description":"Este wiki proporciona una introducci\xf3n completa a las caracter\xedsticas de hardware y al uso de las interfaces de la carrier board reComputer Jetson Robotics J601. Cubre especificaciones detalladas, m\xf3dulos compatibles, instrucciones de configuraci\xf3n y gu\xedas pr\xe1cticas para usar varias interfaces como M.2, Ethernet, USB, CAN, RS485/RS232, UART, I2C, I2S, GPIO, expansi\xf3n de c\xe1mara GMSL2, 5G y GPS, ayudando a los usuarios a comenzar r\xe1pidamente con el desarrollo de rob\xf3tica en la plataforma J601.","permalink":"/es/recomputer_jetson_robotics_j601_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/J501/es_Hardware_Interfaces_Usage","title":"Uso de Interfaces","description":"Uso de Hardware e Interfaces para la placa portadora J501","permalink":"/es/j501_carrier_board_interfaces_usage"}],"unlisted":false}}')}}]);